`,e.jsx(a.li,{children:"Proximidade da data de reserva; "}),`
`,e.jsx(a.li,{children:"Histórico do cliente; "}),`
`,e.jsx(a.li,{children:"Taxas de cancelamento; "}),`
`,e.jsx(a.li,{children:"Taxas de noshow; "}),`
`,e.jsx(a.li,{children:"Desempenho de RevPAR (Receita por quarto disponível); "}),`
